private EclipseNode getRecordFieldForTypeUse(EclipseNode annotationNode, Annotation ast) {
	if (annotationNode.up().getKind() != Kind.TYPE_USE) return null;

	EclipseNode typeNode = annotationNode.directUp();
	ASTNode astNode = typeNode == null ? null : typeNode.get();
	if (!(astNode instanceof TypeReference)) return null;

	Annotation[] anns = EclipseAST.getTopLevelTypeReferenceAnnotations((TypeReference) astNode);
	if (anns == null) return null;
	boolean ok = false;
	for (Annotation ann : anns) if (ast == ann) ok = true;
	if (!ok) return null;

	EclipseNode fieldNode = typeNode.directUp();
	if (fieldNode != null && isRecordField(fieldNode)) return fieldNode;
	return null;
}

